import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AV everyday-crime stories.
extension FollowUpCases {
    static let batchAV: [CaseTemplate] = [changeBoxAgain, libraryAgain, treasurerSecond, keyAgain, petSuppliesAgain, binAgain, jobAdvanceAgain, mallAgain, couponAgain, dwiAgainSchool, tagAgain, kayakAgain, fuelCardAgain, hotelAgain, giftBoxAgain, busAgain, lockerAgain, ediblesAgain, landlordAgain, boardAgain, campAgain]

    static let changeBoxAgain = SmallCases.make(
        key: "story.followup.changeBoxAgain",
        category: .property,
        headlines: ["Change Machine Emptied at Second Laundromat", "Defendant From Coin Door Case Seen on Camera Again"],
        law: "misdLarceny",
        spec: "Stole $290 in coins belonging to {V}, a laundromat, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a different laundromat lost $290 from its change machine. A camera showed {D} at the coin door. {DL} says {D.he} was doing laundry.",
        state: [E(.video, 3, "Camera", "{D} at the coin door with a flat bar."), E(.document, 2, "Coin Log", "$290 short.")],
        defense: [E(.statement, 1, "Laundry", "{DL} says {D.he} was doing laundry.")],
        role: "Laundromat owner",
        exam: [.direct("Tell the jury about your laundromat.", "\"I own a coin laundromat with twenty washers, a dozen dryers, and a change machine by the front window. It is open from six in the morning until ten at night, and I am usually in the back office.\""),
               .direct("What happened to your change machine?", "\"When I emptied the coin box at the end of the week, the coin log was $290 short. The coin door on the machine also showed fresh marks, as if something had been forced under the edge.\""),
               .direct("What did your camera show?", "\"It shows {DL} standing at the coin door with a flat bar, working at the edge of the door for a couple of minutes. {D.He} then reaches inside and puts something in a pocket.\""),
               .direct("Did {DL} have laundry with {D.him}?", "\"No. There was no basket, no bag, and no detergent. {D.He} was not using any machine in the place.\""),
               .direct("What did you do after you saw the footage?", "\"I counted the coin box twice, wrote down the shortage, and called the sheriff's office with the video. A deputy came by the next morning to copy it.\""),
               .direct("How did you recognize {DL}?", "\"A deputy ran the face from my video and found {D.him} from an earlier case in this court. I had never seen {D.him} in my shop before that day.\""),
               .direct("What does a shortage like this cost a business like yours?", "\"Two hundred ninety dollars is about three days of profit for me. I also had to pay a locksmith to repair the coin door.\""),
               .cross("{DL} says {D.he} was there to do laundry, doesn't {D.he}?", "\"That is what {D.he} told the deputy. But the camera shows no clothes, and none of my machines were used by {D.him}.\""),
               .cross("Isn't it possible {DL} was at the coin door to retrieve a lost bill?", "\"People do come to the coin door when the machine eats a bill. They do not usually bring a flat bar to it.\""),
               .cross("Did the owner of any other laundromat ask {DL} to look at a machine?", "\"I have no idea about any other laundromat. Nobody asked {D.him} to touch mine, and I certainly did not.\""),
               .cross("Can you see {DL} actually take the coins on the footage?", "\"You can see {D.his} hand go inside the door and come out toward a pocket. The coins themselves are too small to see on that camera.\""),
               .cross("Was the coin door damaged by that bar?", "\"There were fresh pry marks along the edge of the door. The locksmith said they were made by a flat tool within the past few days.\"")],
        theory: ("{D} pried open a laundromat change machine and emptied its coin box.", "{D} was doing laundry and checking a change machine that had swallowed {D.his} bills."),
        allocution: "\"I was doing my own laundry that day, and I was standing at the coin door for another reason. The money in my pocket was mine. I'm sorry for the trouble at that laundromat.\"",
        truths: ("{DL} had no laundry in the cart.", "The owner of that laundromat had asked {DL} to inspect the machine."),
        defendant: [.direct("Why were you at the coin door that day?", "\"I was at the laundromat to do my wash, and the change machine had swallowed my ten dollars earlier that week. I went to the coin door to see whether it was jammed.\""),
               .direct("Why did you have a flat bar in your hand?", "\"It is mine, from my car trunk, where I keep it with my tools. I had been working on my car in the lot and brought it inside without thinking.\""),
               .direct("Did you take any coins?", "\"No, I did not take any coins. Any money in my pocket was my own, and I had it before I walked in.\""),
               .direct("Where was your laundry?", "\"I had a bag of clothes in my car. I came in to get change for the dryers first and never made it back out to the trunk.\""),
               .direct("Did you tell the deputy that?", "\"Yes, I told the deputy I was doing laundry, and I said it plainly. I did not try to hide the bar.\""),
               .direct("What do you want the owner to know?", "\"I am sorry for the trouble at the laundromat. I should have asked at the counter instead of standing at the coin door.\""),
               .cross("You pried at a coin door with a flat bar, didn't you?", "\"I held the bar against the edge of the door while I looked at it. I did not mean to force it, but I understand why it looks that way.\""),
               .cross("Your laundry was in your car, not in the laundromat, was it?", "\"Yes, it was in my trunk, and I had not carried it in yet. I know that is a weak point for me.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, I was, and I know that history makes anything unusual look worse. I would not have risked another case for $290.\""),
               .cross("The coin log was $290 short that week, wasn't it?", "\"I have heard that number. I cannot say where the coins went, but I did not take that much.\""),
               .cross("You reached inside the coin door, didn't you?", "\"I reached in to feel whether the tray was stuck. I did not take anything out of it.\"")],
        openings: ("A laundromat's coin log came up $290 short, and the owner's camera shows {D} at the change machine's coin door with a flat bar and no laundry in sight. {DL}'s earlier case in this court, in {PRIORDATE} over {PRIOR}, is not what this trial is about, but the video is.", "The defense will present a customer whose bills were swallowed by the machine and who went to look at the coin door. A flat bar in a hand is not the same as taking coins."),
        closings: ("The video shows a flat bar at the coin door, empty hands where a laundry basket should be, and a log that is $290 short. {D} had no machine running and no reason to be at that door.", "A customer, a swallowed ten dollars, and a bar that came from a car trunk. The camera shows a hand going into a coin door but no coins in it, and the State has not proved a theft beyond a reasonable doubt."),
        timeline: [(0, "{D} walks into the laundromat without a laundry basket and goes straight to the change machine."), (0, "The camera records {D} working at the coin door with a flat bar for two minutes."), (1, "The owner counts the coin box and finds it $290 short."), (1, "A deputy copies the video and identifies {D}.")],
        identified: "A camera.",
        mood: .indifferent)

    static let libraryAgain = SmallCases.make(
        key: "story.followup.libraryAgain",
        category: .publicOrder,
        headlines: ["Library Patron Back at Desk After Warning", "Defendant From Library Case Cited Again"],
        law: "disorderly",
        spec: "Disturbed the peace by loud and abusive language in a public library, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} shouted at a different branch's staff over a late fee. A deputy removed {DL}. {DL} says {D.he} was upset about the fee.",
        state: [E(.statement, 3, "Librarian", "{D} shouted at the desk."), E(.video, 2, "Camera", "{D} waves arms.")],
        defense: [E(.statement, 1, "Upset", "{DL} says {D.he} was upset.")],
        role: "Librarian",
        exam: [.direct("What is your job at the library?", "\"I am a librarian at a branch on the east side of the county. I work the circulation desk, handle accounts, and help patrons with fees and holds.\""),
               .direct("What happened at your desk that afternoon?", "\"{DL} came up angry about a late fee on {D.his} account and began shouting at me and the other librarian. Several patrons turned to watch.\""),
               .direct("What did {DL} say?", "\"{D.He} said the fee was a scam and that we were stealing from patrons. {D.He} used some language I will not repeat here, and {D.he} raised {D.his} voice until the whole floor could hear.\""),
               .direct("How long did it go on?", "\"About twenty minutes in all, from the first complaint to the moment the deputy arrived. We asked {D.him} to lower {D.his} voice at least three times.\""),
               .direct("What does the camera show?", "\"It shows {DL} at the desk waving both arms and leaning over the counter. You can see patrons backing away and a parent steering two children out of the children's section.\""),
               .direct("Why was the fee charged?", "\"The account showed a book that was four weeks overdue. We have a posted fee schedule, and the charge matched it.\""),
               .direct("What did you do?", "\"I called the sheriff's office after the third request failed. A deputy came and walked {DL} out, and the branch was quiet again.\""),
               .cross("{DL} says {D.he} was upset about the fee, doesn't {D.he}?", "\"Yes, and I understand a fee can be frustrating. A fee is still not a reason to shout at the staff in a room full of readers.\""),
               .cross("Wasn't the sign explaining the fee missing from the desk?", "\"There is normally a sign. I am not sure it was up that day, because the frame had been taken down for cleaning.\""),
               .cross("Did {DL} touch anyone or threaten anyone?", "\"No, nobody was touched and nobody was threatened. It was loud and angry, and that was the problem.\""),
               .cross("Did {DL} leave when the deputy asked?", "\"Yes, {D.he} went when the deputy asked, and {D.he} did not fight or argue further at that point.\""),
               .cross("Did you check the account dates with {DL} at the time?", "\"I tried to show {D.him} the screen, but {D.he} would not look at it. {D.He} kept talking over me.\"")],
        theory: ("{D} shouted at library staff over a late fee until a deputy removed {D.him}.", "{D} was an upset patron who mixed up the dates on a fee and lost {D.his} temper."),
        allocution: "\"I was upset about that late fee and I shouted at the staff, and the deputy had to remove me. I mixed up the dates on my account. I'm sorry to the librarians who were only doing their jobs.\"",
        truths: ("{DL} had a ban letter from the first branch.", "The branch's fee sign was missing, so the charge looked arbitrary."),
        defendant: [.direct("Why did you go to the library that day?", "\"I went to return a book and to pay a fee I thought was wrong. I was already upset because I had been charged for a book I believed I returned on time.\""),
               .direct("What happened at the desk?", "\"I raised my voice, and I should not have. The staff kept repeating the policy, and I felt like I was not being heard.\""),
               .direct("Did you shout at the librarians?", "\"Yes, I shouted, and I know I embarrassed myself. I was angry about the fee and I took it out on people doing their jobs.\""),
               .direct("Why did you think the fee was wrong?", "\"I mixed up the dates on my account. I believed I had returned the book before the due date.\""),
               .direct("What happened when the deputy arrived?", "\"I left right away. I did not argue with the deputy, and I went home and cooled off.\""),
               .direct("What do you want the librarians to know?", "\"I am sorry to the librarians who were only doing their jobs. They did not deserve to be shouted at.\""),
               .cross("You shouted at the staff for a long time, didn't you?", "\"It felt shorter to me, but I will not argue with the camera. I know it went on too long.\""),
               .cross("You had a ban letter from the first branch, didn't you?", "\"I had a letter from the other branch, and I mixed up what it covered. I did not think it applied here.\""),
               .cross("You were in this court before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"I was, and that makes me feel worse about it. I know I am supposed to be better at keeping my temper.\""),
               .cross("The fee was posted on the fee schedule, wasn't it?", "\"There is a schedule, and I never checked it. I went straight to the desk angry.\""),
               .cross("The deputy had to walk you out, didn't they?", "\"Yes, the deputy had to walk me to the door. I should have gone on my own.\"")],
        openings: ("A librarian asked {D} three times to lower {D.his} voice over a late fee, and {D} kept shouting at the desk until a deputy walked {D.him} out. A camera shows the waving arms and the patrons backing away, and {DL} was in this court before in {PRIORDATE} over {PRIOR}.", "The defense will present a patron who was upset over a fee on a book {D.he} thought was returned on time. A loud complaint at a desk, over a missing sign, is not a crime."),
        closings: ("Twenty minutes of shouting at a desk, three requests to stop, and a deputy needed to end it. Patrons and children in the next room heard every word, and the camera recorded all of it.", "A frustrated patron, a missing fee sign, and a person who left the moment a deputy asked. The State has not shown that {D} meant to disturb anyone's peace, only that {D.he} lost {D.his} temper over a charge."),
        timeline: [(0, "3 p.m.: {D} comes to the circulation desk and begins shouting about the late fee."), (0, "3:10 p.m.: the librarian asks {D} three times to lower {D.his} voice and calls the sheriff."), (0, "3:20 p.m.: a deputy arrives and walks {D} out of the branch.")],
        identified: "A librarian.",
        mood: .indifferent)

    static let treasurerSecond = SmallCases.make(
        key: "story.followup.treasurerSecond",
        category: .whiteCollar,
        headlines: ["Booster Club Reports Missing Dues", "Treasurer From Youth League Case Runs Another Fund"],
        law: "embezzlement",
        spec: "Embezzled $1,900 entrusted to {D} by {V}, a booster club, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} became treasurer of a school booster club, and $1,900 in dues went missing. {DL} says the dues went to a banquet.",
        state: [E(.document, 3, "Bank Records", "$1,900 not deposited."), E(.document, 2, "Receipts", "Parents hold signed receipts.")],
        defense: [E(.statement, 1, "Banquet", "{DL} says the dues paid for a banquet.")],
        role: "Booster club president",
        exam: [.direct("What is your role at the booster club?", "\"I am the club president. We raise money for the school's athletic teams through dues, fundraisers, and a spring banquet.\""),
               .direct("What was {DL}'s job?", "\"{D.He} became our treasurer after the last election. {D.He} collected dues and was supposed to deposit them within a week of receiving them.\""),
               .direct("What went missing?", "\"$1,900 in dues was never deposited. I found out when I reviewed the bank statements before the end of the school year.\""),
               .direct("How do you know parents paid?", "\"Parents hold signed receipts that {DL} wrote out on the club's receipt book. I have copies from eleven families, and each one matches the amount in the book.\""),
               .direct("What did {DL} tell you?", "\"{D.He} said the dues had gone toward a banquet for the athletes. I told {D.him} no banquet had been scheduled or paid for.\""),
               .direct("Was a banquet ever held?", "\"No. We never reserved a hall, ordered food, or sent invitations, and the booster club calendar does not list one.\""),
               .direct("How has this affected the club?", "\"We had to cancel a spring fundraiser and ask families to pay again. Some parents lost trust, and some quit the club.\""),
               .cross("Did {DL} ever tell you a banquet was planned?", "\"{D.He} mentioned it in passing at one meeting. It was never discussed formally or voted on.\""),
               .cross("Who else could edit the club's records?", "\"A notebook of club records is shared among three parents, and any of them could write in it. That includes me.\""),
               .cross("Did you give {DL} permission to hold cash?", "\"The treasurer is allowed to hold dues briefly before depositing them. A week is the rule.\""),
               .cross("Did {DL} hide anything from you?", "\"Not that I know. {D.He} gave me the receipt book when I asked for it.\""),
               .cross("You cannot say what happened to the cash, can you?", "\"No, I cannot. All I know is that it was never deposited and that {DL} was the one holding it.\"")],
        theory: ("{D} kept school booster club dues for personal use.", "{D} held dues for a planned banquet and failed to deposit them."),
        allocution: "\"I never took that money for myself, and I planned to put it to the booster club's use. It was a mistake in my bookkeeping, and I know I was in this court before. I'm sorry to the families. I'll repay the nineteen hundred dollars.\"",
        truths: ("No banquet was held.", "The club's records were kept in a shared notebook that three parents edited."),
        defendant: [.direct("Did you take the dues for yourself?", "\"No, I did not. I never took that money for myself, and I never spent it on anything of my own.\""),
               .direct("What did you plan to do with it?", "\"I planned to use it for a banquet for the athletes. I had talked about it with a few parents, and I kept the cash separate until I could book a hall.\""),
               .direct("Where was the money?", "\"In a locked box at my home. I did not deposit it, because I wanted to have it in one place when I paid the hall.\""),
               .direct("Why did you not deposit it?", "\"That was a mistake in my bookkeeping. I let the weeks go by and I should have deposited it right away.\""),
               .direct("Did you tell the president about the plan?", "\"I mentioned it once, but it was not formal. I should have gotten the club's approval first.\""),
               .direct("What will you do now?", "\"I will repay the nineteen hundred dollars. I am sorry to the families who trusted me.\""),
               .cross("You held $1,900 of other people's money and did not deposit it, didn't you?", "\"Yes, I did, and I know I should not have. The deposit was due within a week.\""),
               .cross("No banquet was ever booked, was one?", "\"No, I never booked one. I had not gotten to it yet.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I know that makes people doubt me. I did not take this job lightly.\""),
               .cross("You wrote the receipts to the families, didn't you?", "\"Yes, I did, and I gave every family a copy. I did not hide any of the payments.\""),
               .cross("You told the president the money paid for a banquet, didn't you?", "\"I told the president it was for a banquet we were planning, and that is the truth. I had no reason to hide anything.\"")],
        openings: ("{D} became treasurer of a school booster club, and $1,900 in dues was never deposited. Parents hold signed receipts for every dollar, no banquet was ever booked, and {DL} was in this court before in {PRIORDATE} over {PRIOR}.", "The defense will present a treasurer who kept the dues in a locked box for a banquet and was careless with the bookkeeping. A missed deposit is a mistake in paperwork, and the State must prove that {D} meant to steal."),
        closings: ("Eleven receipts, $1,900 never deposited, and a banquet that was never booked. A treasurer is trusted to deposit the money, not to hold it, and {D} did not deposit a single dollar of it.", "Careless bookkeeping and a plan that never got off the ground. The State has not shown that {D} meant to use the money for anything but the club, and {D.he} has offered to repay every dollar."),
        timeline: [(-30, "The booster club collects dues, and {D} writes receipts to the families."), (-10, "{D} fails to deposit the $1,900."), (0, "The president reviews the bank statements and finds the dues missing."), (2, "The president confronts {D}, who says the money was for a banquet.")],
        identified: "Bank records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction)

    static let keyAgain = SmallCases.make(
        key: "story.followup.keyAgain",
        category: .family,
        headlines: ["Former Tenant Back Inside Another Apartment", "Defendant From Key Case Enters With Old Key"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} entered another apartment {D.he} used to rent with an old key. The current tenant was home. {DL} says {D.he} came for mail.",
        state: [E(.statement, 3, "Tenant", "{D} used a key to enter."), E(.document, 2, "Notice", "A written notice after the first case.")],
        defense: [E(.statement, 1, "Mail", "{DL} says {D.he} came for mail.")],
        role: "Current tenant",
        exam: [.direct("Tell the jury where you live.", "\"I rent an apartment on the second floor of a small complex. I moved in about four months ago, after the previous tenant moved out.\""),
               .direct("What happened that evening?", "\"I was home on the couch when I heard a key in the lock. {DL} walked in, and I did not know {D.him}.\""),
               .direct("What did {DL} do?", "\"{D.He} stopped just inside the door and looked around. {D.He} said {D.he} used to live there and was looking for mail.\""),
               .direct("How did you react?", "\"I was scared, and I told {D.him} to leave. I called deputies as soon as {D.he} was out the door.\""),
               .direct("Had you received any notice about {DL}?", "\"Yes. After the first case, the landlord gave me a copy of a written notice that said {DL} was not allowed on the property.\""),
               .direct("Did {DL} have any reason to be there?", "\"No. I never invited {D.him}, and there is no mail here for anyone but me.\""),
               .direct("How have you felt since?", "\"I do not feel safe. I changed my locks again and I sleep with a light on.\""),
               .cross("Did {DL} say anything threatening?", "\"No, {D.he} did not threaten me. {D.He} was polite, but {D.he} had no right to come in.\""),
               .cross("Could {DL} have mistaken the apartment for the old one?", "\"{D.He} said {D.he} used to live in it. That does not mean {D.he} still had a right to enter it.\""),
               .cross("Had the locks been changed?", "\"Twice, I was told. I am not sure how the key still worked.\""),
               .cross("Did you ever text {DL} and invite {D.him} to collect mail?", "\"No, I never did, and I did not have {D.his} number.\""),
               .cross("You did not see {DL} take anything, did you?", "\"No, {D.he} did not take anything. {D.He} left when I told {D.him} to.\"")],
        theory: ("{D} used an old key to enter an apartment where someone else now lived.", "{D} went to collect mail and did not realize the new tenant had been told to keep {D.him} out."),
        allocution: "\"I went back to that apartment for my mail, and I used my old key without thinking. I missed that the tenant had changed things. I'm sorry for scaring the person who was home, and I'll turn in the key.\"",
        truths: ("The locks had been changed twice.", "The new tenant had invited {DL} by text to collect old mail."),
        defendant: [.direct("Did you enter that apartment?", "\"Yes, I did, for my mail. I used my old key without thinking.\""),
               .direct("Why did you have an old key?", "\"I lived there before and never turned it in. I had it on my ring with my other keys.\""),
               .direct("Why did you go back?", "\"I was still getting mail with that address on it. I thought I could pick it up and leave.\""),
               .direct("Did you know someone else lived there?", "\"I knew it had been rented, but I did not know the tenant was home. I did not think about it.\""),
               .direct("What happened when the tenant saw you?", "\"I said I was sorry and that I came for mail. I left right away.\""),
               .direct("What will you do now?", "\"I will turn in the key. I am sorry for scaring the person who was home.\""),
               .cross("You used a key to open a door of a home that was not yours, didn't you?", "\"Yes, I did, and I know I should have knocked. I did not think it through.\""),
               .cross("You had received a written notice after your first case, hadn't you?", "\"Yes, I got one, and I missed it. I put it with my mail and did not read it closely.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that I am supposed to be more careful. I did not stop to think.\""),
               .cross("The tenant had not invited you in, had they?", "\"No, nobody invited me, and I understand that now. I assumed it would be fine because the apartment used to be mine.\""),
               .cross("You never called ahead or knocked first, did you?", "\"No, I did not do either, and I regret it. I walked in on a person who had every right to feel safe in that home.\"")],
        openings: ("{D} used an old key to walk into an apartment where a new tenant was home, after a written notice had barred {D.him} from the property. {DL} had a case in this court in {PRIORDATE} over {PRIOR}, and the tenant called deputies at once.", "The defense will present a former tenant who came for mail and left when told to go. An old key and a missed notice are not the same as a deliberate break-in, and nothing was taken from the home."),
        closings: ("A key that turned in the lock, a stranger in the doorway, and a written notice already on file. The tenant never invited {D} in, and {D.he} had no reason to be inside that home.", "A mail error, a mistaken belief, and a person who left as soon as asked. The State has not shown that {D} meant to enter unlawfully or that {D.he} knew {D.he} was not welcome there."),
        timeline: [(-30, "The landlord serves {D} with a written notice after the first case."), (0, "Evening: {D} uses an old key to enter the apartment while the tenant is home."), (0, "The tenant tells {D} to leave and calls deputies.")],
        identified: "The tenant.",
        mood: .indifferent)

    static let petSuppliesAgain = SmallCases.make(
        key: "story.followup.petSuppliesAgain",
        category: .property,
        headlines: ["Pet Store Walkout Again", "Defendant From Dog Supplies Case Filled a Bag"],
        law: "larcenyMerchant",
        spec: "Took pet supplies valued at $150 from {V}, a pet store, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} filled a bag at a different pet store and walked out. {DL} says {D.he} meant to pay.",
        state: [E(.video, 3, "Camera", "{D} fills a bag."), E(.document, 2, "Register Tape", "No sale.")],
        defense: [E(.statement, 1, "Meant to Pay", "{DL} says {D.he} meant to pay.")],
        role: "Pet store employee",
        exam: [.direct("What is your job at the pet store?", "\"I work the sales floor and the front register. I help customers find food, toys, and supplies, and I watch the aisles when it is slow.\""),
               .direct("What did you see that day?", "\"A customer, {DL}, filled a large bag with supplies from three different shelves and headed toward the door. I did not see {D.him} go to a register.\""),
               .direct("What was in the bag?", "\"Dog food, a collar, toys, and some supplements. The shelf prices add up to about $150.\""),
               .direct("Did {DL} stop at any register?", "\"No. We have three registers, and {D.he} walked past all of them. The register tape shows no sale that matches.\""),
               .direct("What did you do?", "\"I followed {D.him} to the door and asked whether {D.he} meant to pay. {D.He} said a phone call distracted {D.him}.\""),
               .direct("What does the store camera show?", "\"It shows {DL} filling the bag, then walking out through the front door. The whole thing takes about four minutes.\""),
               .direct("Why does this matter to the store?", "\"We are a small store, and we cannot afford to lose that much stock. I would rather spend my time helping customers than watching the door.\""),
               .cross("{DL} says {D.he} meant to pay, doesn't {D.he}?", "\"Yes, that is what {D.he} told me. I cannot say what was in {D.his} mind.\""),
               .cross("Was {DL} on the phone while walking out?", "\"{D.He} had a phone in {D.his} hand. I could not tell whether anyone was on the line.\""),
               .cross("Did {DL} run?", "\"No, {D.he} walked, at a normal pace. {D.He} did not try to hide.\""),
               .cross("Did {DL} come back when you called out?", "\"{D.He} stopped when I reached the door. {D.He} did not argue.\""),
               .cross("Was the bag empty when {DL} first picked it up?", "\"I think so, but I did not watch the start. The camera shows it.\"")],
        theory: ("{D} filled a bag at a pet store and walked out past three registers.", "{D} was distracted by a phone call and meant to pay."),
        allocution: "\"A phone call distracted me, and I walked out of that pet store without paying. I meant to pay. I know I was in this court before, and I understand how it looks. I'm sorry to the store, and I'll pay for everything in that bag.\"",
        truths: ("The bag was empty on arrival.", "A receipt in {DL}'s wallet shows a purchase of the items minutes earlier."),
        defendant: [.direct("Did you fill that bag?", "\"Yes, I did. I was shopping for my animals, and I had a long list.\""),
               .direct("Why did you walk out without paying?", "\"A phone call distracted me, and I walked out thinking about it. I meant to pay.\""),
               .direct("Did you walk past three registers?", "\"Yes, and I did not notice them. I was on the phone and heading for my car.\""),
               .direct("What did you say to the employee?", "\"I told the employee I meant to pay and that the call distracted me. I offered to go back in and pay right then.\""),
               .direct("Did you have a receipt for any of it?", "\"I had a receipt for some items I bought a few minutes earlier. I did not realize I had a separate bag.\""),
               .direct("What will you do now?", "\"I will pay for everything in that bag. I am sorry to the store.\""),
               .cross("You filled a bag and left without paying, didn't you?", "\"Yes, I did, and I know how it looks. I was distracted.\""),
               .cross("You walked past three registers, didn't you?", "\"I did, and I did not see them. That is what the call did to me.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I understand why that makes people doubt me. I should have slowed down and walked to a register before I did anything else.\""),
               .cross("The register tape shows no sale, doesn't it?", "\"For that bag, yes. I had paid for other things earlier.\""),
               .cross("You said a phone call distracted you, but you were not talking when you left, were you?", "\"I had just hung up, and I was still holding the phone. I was upset about it.\"")],
        openings: ("A pet store employee watched {D} fill a bag with about $150 of supplies from three shelves and walk past all three registers and out the door. The register tape shows no sale, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a customer who had paid for other items minutes earlier and was distracted by a phone call. Walking out in plain view of a camera is not a plan to steal."),
        closings: ("A full bag, three registers, and no sale on the tape. {D} walked straight out of the front door past every one of them, with about $150 of supplies that had not been paid for.", "A phone call, a receipt for items bought minutes earlier, and a person who stopped when called back. The State has not shown that {D} meant to take that bag without paying, only that {D.he} was distracted."),
        timeline: [(0, "{D} fills a bag with supplies from three shelves at a pet store."), (0, "{D} walks past three registers and out the front door."), (0, "An employee stops {D} at the door, and {D} says a phone call distracted {D.him}."), (1, "The employee gives the camera footage and register tape to a deputy.")],
        identified: "A camera.",
        mood: .indifferent)

    static let binAgain = SmallCases.make(
        key: "story.followup.binAgain",
        category: .property,
        headlines: ["Donation Bin Emptied Again", "Defendant From Clothing Bin Case Linked by Van"],
        law: "misdLarceny",
        spec: "Stole donated clothing valued at $400 belonging to {V}, a charity, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a second charity's bin was emptied. A camera showed {D}'s van. {DL} says the bin was overflowing and abandoned. The loss was put at $400.",
        state: [E(.video, 3, "Camera", "{D}'s van loads bags."), E(.document, 2, "Pickup Log", "Due at noon.")],
        defense: [E(.statement, 1, "Overflowing", "{DL} says the bin looked abandoned.")],
        role: "Charity coordinator",
        exam: [.direct("What is your role at the charity?", "\"I am the coordinator for our clothing donation program. I schedule the pickups from our bins around the county and make sure the donations get to our shelters.\""),
               .direct("What happened to this bin?", "\"A week's worth of donated bags was taken before our pickup. The bin was marked with our name, and the pickup was due at noon that day.\""),
               .direct("What does the pickup log show?", "\"It shows our truck was scheduled to arrive at noon. When our driver got there, the bin was empty and the area around it was clear.\""),
               .direct("What did the camera show?", "\"It shows {DL}'s van pull up at nine in the morning. {D.He} loads bag after bag into the back until the van is full.\""),
               .direct("How did you know the donations were ours?", "\"The bin has our name painted across the front, and our hotline number is on a sign by the door. People drop bags there for us and for no one else.\""),
               .direct("What did the loss amount to?", "\"About $400 in clothing and household goods, by our own estimate. That is more than a week of what that bin collects for the shelter.\""),
               .direct("What did you learn afterward?", "\"Listings for clothes and household items appeared online within a few days. A volunteer recognized a few of our items.\""),
               .cross("{DL} says the bin looked abandoned, doesn't {D.he}?", "\"That is what {D.he} says. It is a donation bin, not an abandoned one, and it has our name on it.\""),
               .cross("Was the bin overflowing that morning?", "\"Yes, it was nearly full, and a few bags sat on the ground beside it. That is normal for the end of the week.\""),
               .cross("Was the sign on the bin faded?", "\"It has been in the sun for a long time, so some of the lettering was dim. The name was still readable.\""),
               .cross("Did the sign tell donors to leave bags beside the bin?", "\"Only when the bin is full. It does not invite anyone to take what is left there.\""),
               .cross("Did {DL} have your permission to take anything?", "\"No, nobody at the charity gave {D.him} permission. I have never met {D.him}.\"")],
        theory: ("{D} loaded a charity's donation bags into a van and sold some online.", "{D} thought an overflowing bin with a faded sign was abandoned."),
        allocution: "\"I thought that bin was abandoned. It was overflowing and the sign had faded, and I loaded it into my van. I'm sorry to the charity. I'll return what I took or pay for it.\"",
        truths: ("The listings appeared online.", "The bin's own sign told donors to leave bags beside it, and {DL} was told to take them."),
        defendant: [.direct("Why did you load those bags into your van?", "\"I thought the bin was abandoned. It was overflowing, and the sign was faded, and bags were piled around it.\""),
               .direct("Did you read the sign?", "\"I saw the sign was faded and I did not look closely. I should have called the number before I touched anything.\""),
               .direct("What did you do with the bags?", "\"I took them home. I sorted through them, and I listed a few items online.\""),
               .direct("Did you plan to sell them?", "\"I sold a few things, yes. I thought nobody would miss clothes in a bin that looked forgotten.\""),
               .direct("What do you want the charity to know?", "\"I am sorry. I should have asked first, and I will return what I took or pay for it.\""),
               .direct("How did you feel when deputies called you?", "\"Embarrassed, and a little scared. I told them where the bags were.\""),
               .cross("You loaded the bags into your van in the morning, in daylight, didn't you?", "\"Yes, I did, and I did it in front of a camera. I was not trying to hide.\""),
               .cross("You listed the items for sale online, didn't you?", "\"Yes, I listed a few of them. I know that makes it look worse.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that I should have learned from that case. I did not think of it that morning.\""),
               .cross("The sign told donors to leave bags beside the bin, didn't it?", "\"It did, and that is part of why I thought they were left for anyone to take.\""),
               .cross("You never called the number on the bin, did you?", "\"No, I did not, and that was a mistake. The hotline number was right there on the sign, and I could have settled it with one call.\"")],
        openings: ("A charity's bin was emptied of a week of donations, about $400 worth, before its noon pickup. A camera shows {D}'s van loading bag after bag, and listings for some of the items turned up online. {DL} was in this court before in {PRIORDATE} over {PRIOR}.", "The defense will present an overflowing bin with a faded sign and bags piled on the ground. {D} loaded the van in broad daylight in front of a camera, which is not what someone does who knows it is stealing."),
        closings: ("A bin with the charity's name painted on it, a camera that shows the van filling bag by bag, and listings online by the end of the week. {D} took a week of donations meant for shelters.", "An overflowing bin, a faded sign, and a person who worked in plain view of a camera in the morning light. The State has not shown that {D} knew the bags belonged to anyone who wanted them back."),
        timeline: [(0, "9 a.m.: {D}'s van arrives at the donation bin and a camera records the loading."), (0, "Noon: the charity's pickup truck arrives and finds the bin empty."), (2, "Listings for some of the donated items appear online.")],
        identified: "A camera.",
        mood: .wantsConviction)

    static let jobAdvanceAgain = SmallCases.make(
        key: "story.followup.jobAdvanceAgain",
        category: .whiteCollar,
        headlines: ["New Job Ad Charges 'Training Fee'", "Defendant From Job Scam Case Posts Again"],
        law: "falsePretenses",
        spec: "Obtained $300 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} paid {D} a $300 fee for a remote job that did not exist. {DL} says the employer was real.",
        state: [E(.digital, 3, "Messages", "{D} asks for $300."), E(.document, 2, "Payment", "$300 to {D}.")],
        defense: [E(.statement, 1, "Real Employer", "{DL} says the employer was real.")],
        role: "Applicant",
        exam: [.direct("What were you looking for when you saw the ad?", "\"I was looking for remote work. I had been out of a job for a few months, and I answered an ad for a position with a company that said it would train me.\""),
               .direct("What did {DL} ask of you?", "\"In a message, {D.he} asked for $300 as a fee before I could start. {D.He} said the fee covered training materials and a background check.\""),
               .direct("Did you pay it?", "\"Yes. I sent $300 as {D.he} asked, and I have the payment record showing the money going to {D.him}.\""),
               .direct("What happened after that?", "\"Nothing. There was no training, no materials, and no job. I wrote several times and got short answers that the job was pending.\""),
               .direct("Did {DL} ever name the employer?", "\"{D.He} gave a company name once, but I could not find any registration for it. The state's business records show no such company.\""),
               .direct("How has this affected you?", "\"It was money I could not afford to lose, and I felt foolish. I had to borrow from my sister for rent that month.\""),
               .direct("What did you do when you realized?", "\"I reported it to the sheriff's office with the messages and the payment record. I also warned a few friends who were looking for work.\""),
               .cross("{DL} says the employer was real, doesn't {D.he}?", "\"That is what {D.he} says, and I cannot prove the opposite. But I could never reach anyone at the company.\""),
               .cross("Did the ad look professional?", "\"It did, with a logo, a job description, and a pay range. That is a big part of why I believed it was real.\""),
               .cross("Did {DL} promise a specific start date?", "\"{D.He} said the job would start once the fee was paid. {D.He} never gave a date, and every time I asked, the answer was that it was pending.\""),
               .cross("Did you check the company before you paid?", "\"I did a quick search and did not find anything alarming. I did not look at state records until later.\""),
               .cross("You do not know what {DL} did with the money, do you?", "\"No, I do not. I know only that it went to {D.him}.\"")],
        theory: ("{D} collected a $300 fee for a remote job that did not exist.", "{D} believed a real employer was behind a training fee and passed the money along."),
        allocution: "\"I took that three hundred dollar fee for training, and I believed the employer was real. The job is still pending. I'm sorry to {V}, and I'll repay the money.\"",
        truths: ("No employer was registered.", "A recruiter confirmed {DL} was authorized to collect fees for a licensed training program."),
        defendant: [.direct("Did you ask for the $300 fee?", "\"Yes, I did. It was for training that the employer required.\""),
               .direct("Was the employer real?", "\"Yes, as far as I knew. I had a contact there, and I was told that the job was pending.\""),
               .direct("Who was the contact?", "\"A recruiter who I was told was authorized to collect fees. I have a message that says so.\""),
               .direct("Did you keep the money?", "\"Some of it went to the program. I kept a small share as a finder's fee.\""),
               .direct("Why did you stop answering {V.him}?", "\"I was waiting for word from the employer, and I had nothing to tell {V.him}. I should have said so.\""),
               .direct("What will you do about the money?", "\"I will repay the $300 in full. I am sorry to {V}.\""),
               .cross("You asked {V} for $300 before there was a job, didn't you?", "\"Yes, because that was the process I was told about. I did not question it.\""),
               .cross("No company was registered under the name you gave, was there?", "\"I did not know that at the time. The job is still pending as far as I know.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes this look like a pattern. I did not mean to repeat it.\""),
               .cross("You kept some of the money, didn't you?", "\"Yes, a small part, as a fee I was told I could keep.\""),
               .cross("You never gave {V} a refund, did you?", "\"No, I did not, and that was wrong. I should have returned the money the moment the job did not come through.\"")],
        openings: ("{V} paid {D} a $300 fee for a remote job that never existed. The messages show {DL} asking for the money, the payment record shows it going to {D.him}, and no company was ever registered. {DL} was in this court before in {PRIORDATE} over {PRIOR}.", "The defense will present a recruiter who believed an employer was real and who was told {D.he} could collect fees for training. A bad job offer is not the same as a lie told on purpose."),
        closings: ("A fee requested in writing, a payment recorded, and an employer no one can find in any state record. {V} lost $300 to a job that never started, and every message {D} sent said it was pending.", "A recruiter who believed in a training program and a message saying {D.he} was authorized to collect fees. The State has not shown that {D} knew there was no job when {D.he} took the money."),
        timeline: [(-5, "{V} answers an online ad for a remote job and {D} asks for a $300 fee."), (0, "{V} pays the $300 to {D}."), (10, "{V} reports it to the sheriff's office.")],
        identified: "Messages.",
        mood: .wantsConviction)

    static let mallAgain = SmallCases.make(
        key: "story.followup.mallAgain",
        category: .publicOrder,
        headlines: ["Banned Shopper Returns to Another Mall", "Defendant From Mall Ban Case Cited Again"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a shopping center, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} entered a different mall under a ban. {DL} says the ban covered only one mall.",
        state: [E(.document, 3, "Ban Letter", "A ban for all properties."), E(.video, 2, "Camera", "{D} in the food court.")],
        defense: [E(.statement, 1, "One Mall", "{DL} says the ban covered one mall.")],
        role: "Mall security manager",
        exam: [.direct("What is your position at the mall?", "\"I am the security manager. I oversee the guards and the cameras, and I keep the ban letters we give to people who are no longer allowed on our properties.\""),
               .direct("Was there a ban in place against {DL}?", "\"Yes, a written ban issued after an earlier incident. It covers every property our company manages, which includes this mall and the first one across town.\""),
               .direct("Did {DL} sign that letter?", "\"Yes, {D.he} signed it and initialed the bottom of each page. I have the signed original in our file, and I have shown it to the deputy.\""),
               .direct("What did the camera show on the day in question?", "\"{DL} walking through the food court, then riding an escalator up to a clothing store. The time stamp is early afternoon on {DATE}.\""),
               .direct("What did you do when you saw {D.him}?", "\"I recognized {D.him} from the earlier incident and called the sheriff's office. I asked two guards to keep {D.him} in sight until deputies arrived.\""),
               .direct("How did {DL} react when you approached?", "\"{D.He} said {D.he} thought the ban covered only the first mall. {D.He} did not run or argue, and {D.he} was polite the whole time.\""),
               .direct("Why does the ban cover both malls?", "\"We manage them together and share one security staff and one set of cameras. The letter says so in plain language, in the second paragraph.\""),
               .cross("{DL} says the ban covered only one mall, doesn't {D.he}?", "\"That is what {D.he} told me at the scene. The letter lists all properties managed by the company, and both malls are among them.\""),
               .cross("Is the second mall named in the letter?", "\"The letter says all properties. The first mall is named as the place where the earlier incident happened, which may be how someone could misread it.\""),
               .cross("Did {DL} ever write or call to ask how far the ban reached?", "\"No, {D.he} never contacted us at all. The first I learned of it was when a guard called me about the food court.\""),
               .cross("Was {DL} causing any trouble in the mall?", "\"No, {D.he} was walking and shopping quietly. The only issue was the ban itself, and not anything {D.he} did while inside.\""),
               .cross("You cannot say what {DL} understood when {D.he} signed, can you?", "\"No, I cannot. I can tell you what the letter says and that {D.he} initialed every page of it.\"")],
        theory: ("{D} entered a mall under a ban that covers all of the company's properties.", "{D} read the ban as covering only one mall and went shopping."),
        allocution: "\"My ban covered one mall, as I understood it, and I went to a different mall to shop. I know I was in this court before, and I should have asked. I'm sorry for the misunderstanding. I'll stay out of both malls.\"",
        truths: ("The letter listed all malls.", "The ban letter named only the first mall."),
        defendant: [.direct("Did you know you were banned from malls?", "\"I knew I was banned from the first mall. I understood the ban to cover only that one, and I thought the second mall was separate.\""),
               .direct("Why did you go to the other mall?", "\"I needed a few things and it was the closest place to my work. I was not trying to cause trouble.\""),
               .direct("Did you read the ban letter?", "\"I signed it and initialed each page, but I did not read it closely. I was nervous that day, and I wanted to leave.\""),
               .direct("What happened when security stopped you?", "\"I told them what I believed about the ban, and I left when they asked. I did not argue or run.\""),
               .direct("What did you do inside the mall?", "\"I walked through the food court and went into one store. I did not cause any trouble.\""),
               .direct("What will you do now?", "\"I will stay out of both malls. I am sorry for the misunderstanding.\""),
               .cross("You signed and initialed the ban letter, didn't you?", "\"Yes, I did, and I know that means I agreed to what was in it. I should have read each page.\""),
               .cross("The letter lists all properties, doesn't it?", "\"I understand that now, after reading it again. At the time, I read it as being about the first mall only.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I know that makes me look like someone who does not learn. I should have asked someone about the ban.\""),
               .cross("The letter used the first mall only as an example, didn't it?", "\"I took the example to be the whole ban, and I did not think about the other mall at all.\""),
               .cross("You never called anyone to ask whether you could go to the second mall, did you?", "\"No, I did not, and I regret it. One phone call would have kept me out of this courtroom.\"")],
        openings: ("{D} signed and initialed a ban letter that covers every property the mall company manages, then walked into the food court of its second mall on {DATE}. A camera shows {D} there, and {DL} was in this court before in {PRIORDATE} over {PRIOR}, so {D.he} knew what a ban meant.", "The defense will present a ban letter that named only the first mall as its example. A shopper who read a notice in good faith and then browsed quietly in one store has not defied anything."),
        closings: ("A signed letter, initials on every page, and a camera that shows {D} in the food court of a mall the letter plainly covers. The ban says all properties, and {D} agreed to it in writing.", "A letter that used one mall as its example and a shopper who read it that way. The State has not shown that {D} knew {D.he} was banned from that mall, or that {D.he} meant to ignore a ban."),
        timeline: [(-60, "The mall company gives {D} a written ban covering all of its properties, and {D} signs it."), (0, "Early afternoon: {D} walks into the food court of the second mall and a camera records it."), (0, "Security recognizes {D} and calls deputies.")],
        identified: "A ban letter.",
        mood: .indifferent)

    static let couponAgain = SmallCases.make(
        key: "story.followup.couponAgain",
        category: .whiteCollar,
        headlines: ["Copied Coupons at New Chain", "Defendant From Coupon Case Redeems More"],
        law: "falsePretenses",
        spec: "Obtained $600 in merchandise from {V}, a retailer, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} redeemed copied coupons at another chain. {DL} says a friend gave them.",
        state: [E(.document, 3, "Redemptions", "Identical barcodes."), E(.video, 2, "Camera", "{D} at the register.")],
        defense: [E(.statement, 1, "Friend's Coupons", "{DL} says a friend gave them.")],
        role: "Loss-prevention officer",
        exam: [.direct("What is your job?", "\"I am a loss-prevention officer for a regional grocery chain. I review redemption reports and investigate any pattern that looks wrong.\""),
               .direct("What did you find in the reports?", "\"A group of coupons with identical barcodes, redeemed over several visits. A real coupon carries a unique code, so duplicates are a red flag.\""),
               .direct("What was the total value?", "\"$600 in discounts over a short period. That is a very large amount for one customer's weekly shopping.\""),
               .direct("What does the register camera show?", "\"It shows {DL} handing a stack of coupons to the cashier on several visits. The stack looks the same each time, and the cashier scans them one by one.\""),
               .direct("How did you tie the coupons to {DL}?", "\"The loyalty card used at the register belongs to {DL}. All of the redemptions are on that one account.\""),
               .direct("What did the manufacturer say about the codes?", "\"The manufacturer said each code is supposed to be used once, and that these were duplicates that had been printed or photocopied.\""),
               .direct("Why does this matter to a grocery chain?", "\"Counterfeit coupons cost us and the manufacturer real money, and honest customers end up paying for it in prices at the register.\""),
               .cross("{DL} says a friend gave {D.him} the coupons, doesn't {D.he}?", "\"That is what {D.he} told me. {D.He} never gave me a name for the friend, so I could not check it.\""),
               .cross("Could coupons have been mailed to {DL} by a legitimate coupon club?", "\"If such a club duplicates barcodes, that could happen. I looked for one and did not find any record of it.\""),
               .cross("Was a printer found?", "\"A printer was in {D.his} car. I cannot tie it to those coupons directly, because the investigators did not test it.\""),
               .cross("Did {DL} look nervous at the register?", "\"No, {D.he} was calm, and {D.he} used the same routine each time. {D.He} did not try to hide the card.\""),
               .cross("You cannot say who printed the coupons, can you?", "\"No, I cannot. I can say only that the loyalty card on the account is {D.his}, and that the codes were duplicated.\"")],
        theory: ("{D} redeemed copied coupons with duplicate barcodes at several registers.", "{D} used coupons that a friend gave {D.him} and did not know they were copies."),
        allocution: "\"A friend gave me those coupons, and I used them at work shopping runs without thinking. I never made any copies. I'm sorry to the store, and I'll stay away from coupons altogether.\"",
        truths: ("A printer was in the car.", "The coupons were mailed to {DL} by a coupon club that duplicates barcodes."),
        defendant: [.direct("Did you copy those coupons?", "\"No, I never made copies of anything. I do not know how to duplicate a barcode, and I never tried.\""),
               .direct("Where did the coupons come from?", "\"A friend gave them to me in a stack, and I used them during my shopping runs after work. I thought they were real.\""),
               .direct("Who is the friend?", "\"A person I know from work. I do not want to get that person into trouble, but I will tell the court the name if I am asked.\""),
               .direct("Why did you have a printer in your car?", "\"It is for work. I print forms and receipts for my clients when I visit them.\""),
               .direct("Did you know the coupons were fake?", "\"No, I did not. If I had known, I would never have handed them over under my own name.\""),
               .direct("What will you do now?", "\"I will stay away from coupons altogether. I am sorry to the store for the loss.\""),
               .cross("You redeemed $600 worth of coupons over several visits, didn't you?", "\"Yes, I did, and I did not add it up as I went. Looking back, it was far more than I should have used.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know how that history looks beside this charge. I am not a person who sets out to cheat a store.\""),
               .cross("The barcodes on all of them were identical, weren't they?", "\"I did not look at the barcodes. I handed over what I was given, and the register took them.\""),
               .cross("You never asked your friend where the coupons came from, did you?", "\"No, I did not ask. I assumed they came from a newspaper or a mailer.\""),
               .cross("The loyalty card used was your own, wasn't it?", "\"Yes, it was, and I used it every time. I was not hiding who I was.\"")],
        openings: ("A grocery chain's loss-prevention officer found $600 in redeemed coupons with identical barcodes, all tied to {D}'s loyalty card. A register camera shows {D} handing over the stack, and {DL} was in this court before in {PRIORDATE} over {PRIOR}.", "The defense will present a shopper who received coupons from a friend and used them under {D.his} own loyalty card, in front of a camera. That is not what someone does who knows they are fake."),
        closings: ("Identical barcodes, a loyalty card in {D}'s name, and a stack of coupons handed to a cashier again and again, for $600 in discounts. Real coupons do not come in duplicate, and the manufacturer said so.", "A friend's coupons and a shopper who used them under {D.his} own name and loyalty card, in front of a camera. The State has not shown that {D} knew they were copies or made any of them."),
        timeline: [(0, "{D} redeems a stack of coupons at a grocery register while the camera records it."), (7, "The chain's system flags the duplicate barcodes."), (10, "Loss prevention ties the redemptions to {D}'s loyalty card and refers the matter to deputies.")],
        identified: "Redemption records.",
        mood: .indifferent)

    static let dwiAgainSchool = SmallCases.make(
        key: "story.followup.dwiAgainSchool",
        category: .traffic,
        headlines: ["Parent Stopped After Evening Event", "Defendant From School-Run DWI Stopped Again"],
        law: "dwi",
        spec: "Operated a vehicle on a street while subject to an impairing substance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was stopped after a school event and blew 0.10. {DL} says {D.he} had two drinks.",
        state: [E(.forensic, 3, "Breath Test", "0.10."), E(.statement, 3, "Deputy", "Odor and slurred speech.")],
        defense: [E(.statement, 1, "Two Drinks", "{DL} says {D.he} had two drinks.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I am a sheriff's deputy on the evening patrol. I work traffic stops, and I am certified in impaired driving enforcement and the breath instrument.\""),
               .direct("Why did you stop {DL}?", "\"I saw the car leave the parking lot after a school event, drifting inside its lane. I followed it for about half a mile, watched it cross the center line once, and pulled it over.\""),
               .direct("What did you notice when you spoke with {DL}?", "\"A strong odor of alcohol coming from the car, and {D.his} speech was slurred. {D.His} eyes were red and glassy, and {D.he} fumbled with {D.his} license.\""),
               .direct("What did the breath test show?", "\"A reading of 0.10, which is over the legal limit. I administered it on the certified instrument at the station after the field tests.\""),
               .direct("What did {DL} tell you about drinking?", "\"{D.He} said {D.he} had two drinks after the school event. {D.He} also said {D.he} drank water after that, because {D.he} knew {D.he} would be driving.\""),
               .direct("What did you find in the car?", "\"A cup in the cupholder. I did not see any open containers or bottles.\""),
               .cross("Is it possible that two drinks would produce 0.10?", "\"It depends on the person's size and the time. I have seen it happen, but it is not typical.\""),
               .cross("Was the breath instrument within its calibration window?", "\"It is supposed to be. I did not personally check the maintenance records before I used it.\""),
               .cross("Did you test what was in the cup?", "\"No, I did not. {DL} said it was water, and I had no reason to doubt that at the scene.\""),
               .cross("Did {DL} perform the field tests well?", "\"{D.He} did poorly on one and acceptably on another. I would say the results were mixed.\""),
               .cross("Was {DL} cooperative with you?", "\"Yes, {D.he} was polite and did everything I asked. {D.He} did not argue or try to leave.\"")],
        theory: ("{D} drove away from a school event with a breath reading of 0.10.", "{D} had two drinks, drank water afterward, and was fine to drive."),
        allocution: "\"I had two drinks after the school event, and I drank water afterward. I know I was in this court before, and I should have called a ride. I'm sorry for putting people at risk on that road.\"",
        truths: ("A cup was in the cupholder.", "The breath instrument was out of its calibration window that week."),
        defendant: [.direct("Were you drunk when you drove?", "\"No, I was not. I had two drinks after the event and I believed I was fine to drive.\""),
               .direct("What did you drink?", "\"Two drinks, over about an hour, at a table with friends. After that, I drank water and sat for a while before leaving.\""),
               .direct("What was in the cup in your car?", "\"Water. I filled it from the fountain before I left, because I wanted to be sure I was sober.\""),
               .direct("Why did you decide to drive?", "\"I felt fine, and my home is only a few minutes away. I should have called a ride, and I know that now.\""),
               .direct("How was the stop?", "\"The deputy was polite, and I did what was asked. I told the truth about the two drinks.\""),
               .direct("What do you regret?", "\"I regret putting people at risk on that road. I am sorry for what I did.\""),
               .cross("You had been drinking before you drove, hadn't you?", "\"Yes, two drinks, and I should not have driven after them. I made a bad decision.\""),
               .cross("The test read 0.10, didn't it?", "\"That is what the instrument said. I did not feel that impaired, but I cannot argue with a machine.\""),
               .cross("You came before this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I should have known better than to get behind the wheel again. I let myself believe I was fine.\""),
               .cross("Your speech was slurred when the deputy talked to you, wasn't it?", "\"I was tired, and I had been up since early morning. I did not think my speech was slurred.\""),
               .cross("You did not call anyone for a ride, did you?", "\"No, I did not. I should have, and I will not make that mistake again.\"")],
        openings: ("After a school event, a deputy followed {D}'s car, watched it cross the center line, and smelled alcohol. A breath test read 0.10, and {DL} was in this court before in {PRIORDATE} over {PRIOR}, on a road that was full of families that night.", "The defense will present a driver who had two drinks, drank water afterward, and cooperated fully with the deputy. A breath instrument must be accurate and in calibration, and the State must prove that it was."),
        closings: ("A strong odor, slurred speech, a car drifting over the center line, and a reading of 0.10. {D} drove away from a school event with families and children on the road, and had been in this court before.", "Two drinks and water, an instrument that may have been out of its calibration window, and a polite driver who did what was asked. The State has not proved the reading beyond a reasonable doubt."),
        timeline: [(0, "The school event ends and {D} leaves the parking lot."), (0, "A deputy follows the car for half a mile and stops it after it crosses the center line."), (0, "A breath test at the station reads 0.10.")],
        identified: "A deputy.",
        aggravating: ["The defendant was impaired at the time of the offense"],
        mood: .indifferent)

    static let tagAgain = SmallCases.make(
        key: "story.followup.tagAgain",
        category: .traffic,
        headlines: ["Another Chase Over an Expired Tag", "Defendant From Hedge Keys Case Flees Again"],
        law: "fleeing",
        spec: "Operated a motor vehicle on a highway while fleeing a law enforcement officer, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} fled from a stop in a car with an expired tag. {DL} says {D.he} was not the driver.",
        state: [E(.video, 3, "Dash Camera", "A car flees."), E(.physical, 2, "Keys", "Keys in the ignition.", .search)],
        defense: [E(.statement, 1, "Not the Driver", "{DL} says {D.he} was not the driver.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I am a sheriff's deputy on patrol. I stop vehicles for equipment and registration violations, and I handle any pursuits that follow.\""),
               .direct("What first caught your attention?", "\"A car with an expired registration tag, driving ahead of me on a county road in the afternoon. I turned on my lights to make a stop.\""),
               .direct("What did the car do?", "\"It sped up and did not stop. It ran two stop signs and made a sharp turn onto a side street.\""),
               .direct("What does your dash camera show?", "\"It shows the car fleeing with my lights and siren on. You can see it take the turn at speed and the tires slide.\""),
               .direct("How did the chase end?", "\"The car came to a stop on a side street about half a mile away. When I got there, the driver's door was hanging open.\""),
               .direct("Where was {DL} when you arrived?", "\"Standing near the car, at the edge of the road. {D.He} was breathing hard and was not wearing a seat belt.\""),
               .cross("Did you see who was driving?", "\"No, I did not. I was behind the car the whole time, and I could not see into it.\""),
               .cross("Did you see {DL} get out of the car?", "\"No, I arrived after the car had stopped. I did not see anyone get out.\""),
               .cross("Could there have been a passenger?", "\"Yes, it is possible. The car is large enough for several people, and a passenger could have run.\""),
               .cross("Who owns the car?", "\"The registration shows it belongs to a family member of {DL}'s. I have not spoken with that person.\""),
               .cross("You cannot say who was driving, can you?", "\"No, I cannot. I can tell you who was standing next to the car and whose phone was inside.\"")],
        theory: ("{D} drove a car with an expired tag away from a deputy and then ran.", "{D} was a passenger who panicked and ran when the car stopped."),
        allocution: "\"I was not driving that car, and I was scared when the deputy stopped us. I ran, and that was a panic. The car is shared among family members. I'm sorry for running.\"",
        truths: ("{DL}'s phone was in the console.", "A passenger who fled was later identified as the driver."),
        defendant: [.direct("Did you drive that car?", "\"No, I did not drive it. I was a passenger when the deputy turned on the lights.\""),
               .direct("Why did you run?", "\"I was scared when the deputy stopped us. I had been in trouble before, and I panicked.\""),
               .direct("Whose car was it?", "\"It is shared among family members. Several of us drive it, and I had been using it earlier in the week.\""),
               .direct("Where were you sitting?", "\"In the passenger seat. I got out when the car stopped and ran for the edge of the road.\""),
               .direct("Who was driving?", "\"Another person, who I do not want to name. I do not want to cause that person more trouble.\""),
               .direct("What do you regret?", "\"I am sorry for running, and for scaring the deputy. I should have stayed in the car.\""),
               .cross("You ran from a deputy, didn't you?", "\"Yes, I ran on foot from the car, and I know it looked bad. I panicked.\""),
               .cross("Your phone was in the console, wasn't it?", "\"Yes, it was in the center, where I always put it. It does not show where I was sitting.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and that is part of why I was afraid. I did not want another case.\""),
               .cross("The keys were in the ignition, weren't they?", "\"I did not see who left them there.\""),
               .cross("You never told the deputy who was driving, did you?", "\"No. I was scared and I did not want to get anyone else in trouble.\"")],
        openings: ("A deputy tried to stop a car with an expired tag, and the car sped away, ran two stop signs, and stopped on a side street. {D} was standing next to it with the keys in the ignition, and {DL} was in this court before in {PRIORDATE} over {PRIOR}.", "The defense will present a passenger in a shared family car who panicked when the lights came on. Nobody saw who was driving, and {D} says it was not {D.him}, only someone who ran."),
        closings: ("The car fled, the keys were in the ignition, the engine was still warm, and {D} was the person standing next to it when the deputy arrived. A driver does not stand there by chance.", "A shared car, a passenger who ran, and a deputy who never saw the driver. The State has not shown beyond a reasonable doubt who was behind the wheel when that car fled."),
        timeline: [(0, "A deputy lights up a car with an expired tag on a county road."), (0, "The car flees, runs two stop signs, and stops on a side street."), (0, "The deputy finds {D} standing near the car with the keys in the ignition.")],
        identified: "A dash camera.",
        mood: .indifferent)

    static let kayakAgain = SmallCases.make(
        key: "story.followup.kayakAgain",
        category: .property,
        headlines: ["Another Dock Loses a Kayak", "Defendant From Kayak Case Linked by Truck"],
        law: "misdLarceny",
        spec: "Stole a kayak valued at $500 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a kayak was cut from another dock. A camera showed {D}'s truck. {DL} says {D.he} found it adrift. The loss was put at $500.",
        state: [E(.video, 3, "Camera", "{D}'s truck backs to the dock."), E(.physical, 2, "Kayak", "A kayak in {D}'s truck.", .search)],
        defense: [E(.statement, 1, "Adrift", "{DL} says {D.he} found it adrift.")],
        role: "Kayak owner",
        exam: [.direct("What happened to your kayak?", "\"I kept a fishing kayak tied to my dock with a steel cable and a padlock. One morning the cable was cut and the kayak was gone, and it was worth about $500.\""),
               .direct("How did you know it was yours?", "\"It has a hull number and my initials on the stern from when I bought it. I also have the receipt and a photograph of it on the dock.\""),
               .direct("What did the neighbor's camera show?", "\"A truck backing down to the water at night, and {DL} getting out to work at the dock. {D.He} loads something long and dark into the bed and leaves.\""),
               .direct("Where was the kayak found?", "\"In the bed of {DL}'s truck when a deputy stopped it a few days later. It was still wearing the strip of cable that had been tied through the handle.\""),
               .direct("Was the kayak tied or loose when you last saw it?", "\"Tied. I locked it myself the evening before, and I checked the padlock before I went in.\""),
               .direct("What did the loss mean to you?", "\"I fish from that kayak most mornings, and it was a gift from my father. I had to borrow a boat for two weeks while the sheriff's office sorted it out.\""),
               .direct("Did you ever give {DL} permission to take it?", "\"No. I do not know {D.him}, and I never gave anyone permission to cut the cable.\""),
               .cross("{DL} says the kayak was adrift, doesn't {D.he}?", "\"That is what {D.he} told the deputy. But it was locked to my dock, and a cable does not cut itself.\""),
               .cross("Could the cable have broken in a storm?", "\"It was a steel cable with a padlock, and there was no storm that night. A bolt cutter cut it clean.\""),
               .cross("Did a note ever say the kayak was free?", "\"No. I have never left a note on a boat I own.\""),
               .cross("Was a cable found in the truck?", "\"I was told a cut piece of cable was found. I did not see it myself, and I cannot say who cut it.\""),
               .cross("You were asleep when it was taken, weren't you?", "\"Yes, I was, and I did not see who took it. I know only what the camera and the deputy found.\"")],
        theory: ("{D} cut a kayak from a dock and drove off with it.", "{D} found a kayak adrift and kept it too long."),
        allocution: "\"I found that kayak adrift near the dock and brought it back in my truck, keeping it in my garage. I never cut anything loose. I'm sorry to the owner, and I'll give it back right away.\"",
        truths: ("A cut cable was in the truck.", "The kayak's owner had left it loose with a note 'free to a good home'."),
        defendant: [.direct("Where did you find the kayak?", "\"Drifting near a dock about a quarter mile from where I was fishing. It was loose in the water, and I thought it was lost.\""),
               .direct("What did you do with it?", "\"I towed it to shore and put it in the bed of my truck. I meant to hold it until I could find the owner.\""),
               .direct("Did you cut any cable?", "\"No, I never cut anything. A bolt cutter was in my truck for work, but I did not use it on that kayak.\""),
               .direct("Where did you keep the kayak?", "\"In my garage. I never sold it or tried to use it for fishing.\""),
               .direct("Did you try to find the owner?", "\"I meant to, and I put it off. I should have called the sheriff's office the first day.\""),
               .direct("What do you want the owner to know?", "\"I am sorry, and I will give the kayak back right away. I should have turned it in instead of keeping it.\""),
               .cross("A truck backing to the dock is on the camera, isn't it?", "\"Yes, that was me, because the kayak had drifted to a dock near my house. I did not know whose dock it was.\""),
               .cross("The kayak had a strip of cut cable on its handle, didn't it?", "\"It did, and that is what made me think it had broken loose. I did not cut it myself.\""),
               .cross("You came before this court in {PRIORDATE} over {PRIOR}, didn't you?", "\"Yes, and I know that history makes you doubt me. I picked up that kayak because I thought it was abandoned.\""),
               .cross("You never reported finding it, did you?", "\"No, I did not, and that was a mistake. I waited too long, and then a deputy stopped me.\""),
               .cross("The kayak was found in your truck bed, wasn't it?", "\"Yes, a few days after I picked it up. I had meant to take it to the sheriff's office on my day off.\"")],
        openings: ("A kayak worth $500 was cut from a neighbor's dock at night, and a camera shows {D}'s truck backing to the water. A deputy later found the kayak in the truck bed, still wearing a strip of cut cable, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a fisherman who found the kayak drifting and meant to return it. A person who gives a kayak a ride in an open truck bed is not hiding a theft."),
        closings: ("A locked cable cut clean, a truck on the dock camera, and a kayak found in the truck bed days later with the cut cable still attached. That is what taking looks like.", "A kayak that drifted, a driver who towed it in, and a delay in calling the owner. The State has not shown that {D} was the one who cut that cable, only that {D.he} picked up something that was loose."),
        timeline: [(0, "Night: {D}'s truck backs down to the dock and a neighbor's camera records it."), (1, "The owner finds the cable cut and the kayak gone."), (4, "A deputy stops {D}'s truck and finds the kayak in the bed.")],
        identified: "A camera.",
        mood: .indifferent)

    static let fuelCardAgain = SmallCases.make(
        key: "story.followup.fuelCardAgain",
        category: .whiteCollar,
        headlines: ["Fuel Card Charges Again at New Employer", "Defendant From Fuel Card Case Hired Elsewhere"],
        law: "misdLarceny",
        spec: "Stole gasoline valued at $230 belonging to {V}, a delivery company, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a delivery company found weekend fuel charges on a card assigned to {D}. {DL} says the charges were for the route van.",
        state: [E(.document, 3, "Card Statement", "11 weekend charges."), E(.video, 2, "Station Camera", "{D} at a pump in a personal car.")],
        defense: [E(.statement, 1, "Route Van", "{DL} says the charges were for the route van.")],
        role: "Delivery company manager",
        exam: [.direct("What is your role at the delivery company?", "\"I am the operations manager. I assign routes, I hand out the fuel cards, and I review the card statements every month.\""),
               .direct("What did you find on {DL}'s card statement?", "\"Eleven fuel charges on weekends. The company does not run routes on weekends, so I could not account for them.\""),
               .direct("What was the total?", "\"$230. Each charge was small, between fifteen and thirty dollars, which is why they were hard to see at first.\""),
               .direct("What did the station camera show?", "\"{DL} at a pump, fueling a personal car. It is not the route van, and it is a different color and plate.\""),
               .direct("Why does that matter?", "\"The card is for company vehicles on company routes. Fueling a personal car on a weekend is not covered by anything we have written.\""),
               .direct("What did {DL} tell you when you asked?", "\"{D.He} said the charges were for the route van on extra routes. I asked who had assigned them, and {D.he} did not have an answer.\""),
               .direct("What did you do?", "\"I printed the statement and the video and gave both to the sheriff's office. I also took the card back.\""),
               .cross("Did {DL} ever work extra routes for the company?", "\"A few, during a rush before the holidays. Those were on weekdays and were approved by me.\""),
               .cross("Did you ever tell {DL} the card could be used for a personal car on route runs?", "\"I told {D.him} once that the card could be used for runs if the van was in the shop. I did not say anything about weekends.\""),
               .cross("Did you check the van's fuel logs?", "\"The van's own logs do not match those weekend charges. That is part of why I looked.\""),
               .cross("Was the card used at the same station each time?", "\"Mostly at the same two stations near {D.his} home. Neither is on any of our delivery routes, which is why I noticed.\""),
               .cross("You never asked {DL} about the weekend charges before this, did you?", "\"No, I did not look closely until the month-end review. Each charge was small, and I did not notice the pattern until I added them up.\"")],
        theory: ("{D} used a company fuel card for weekend fill-ups in a personal car.", "{D} used the card for the route van and for personal-car route runs the manager had approved."),
        allocution: "\"I used that fuel card for the van on extra routes the company assigned me. The weekend charges were for work. I borrowed the card once when mine was empty. I'm sorry for the confusion, and I'll pay for anything I owe.\"",
        truths: ("The camera shows a personal car.", "The manager had told {DL} the card could fuel a personal car for route runs."),
        defendant: [.direct("Did you use the fuel card?", "\"Yes, I used it for the route van, and for a few extra routes the company assigned me.\""),
               .direct("Were the weekend charges for work?", "\"Yes. We had a rush, and I took extra routes on Saturdays and Sundays. The manager knew I was working them.\""),
               .direct("What about the personal car at the station?", "\"The van was in the shop that weekend, and the manager had told me to use my own car for route runs. I filled up my car with the card.\""),
               .direct("Did you borrow another driver's card?", "\"Once. Mine was empty, and I borrowed one from a coworker for a single fill-up.\""),
               .direct("Did you keep any record of the extra routes?", "\"I wrote them on a delivery sheet, but I did not turn it in. I should have.\""),
               .direct("What will you do about it?", "\"I will pay for anything I owe. I am sorry for the confusion.\""),
               .cross("You used the company card for a personal car, didn't you?", "\"Yes, on a route run, when the van was in the shop. The manager told me to do it.\""),
               .cross("Eleven weekend charges is a lot of weekends, isn't it?", "\"It was a long rush, and I worked many weekends. I did not see how it would look.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes my explanation harder to believe. I am not trying to cheat the company.\""),
               .cross("You cannot show a written record of those routes, can you?", "\"No, I cannot. I did not keep the delivery sheets, and I know that leaves you only my word for it.\""),
               .cross("You did not tell the manager about the borrowed card, did you?", "\"No, I did not, and I should have. I thought it was too small to mention, and I was wrong about that.\"")],
        openings: ("A delivery company's fuel card assigned to {D} was used for eleven weekend charges totaling $230, and a station camera shows {D} fueling a personal car. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the company does not run routes on weekends.", "The defense will present extra routes that the company itself assigned, and a manager who said the card could fuel a personal car on route runs. The paperwork was poor, but the intent was to work."),
        closings: ("Eleven weekend charges, a personal car at the pump, and a card that was meant for company vehicles on company routes. The company runs no weekend routes, and the van's own logs do not match.", "A rush season, extra routes, and an oral permission that was never written down. The State has not shown that {D} meant to steal fuel, only that the paperwork behind a busy season was incomplete."),
        timeline: [(-30, "The company gives {D} a fuel card."), (0, "{D} fuels a personal car on a weekend and a station camera records it."), (0, "The manager reviews the statement and finds eleven weekend charges.")],
        identified: "A card statement.",
        mood: .wantsConviction)

    static let hotelAgain = SmallCases.make(
        key: "story.followup.hotelAgain",
        category: .property,
        headlines: ["Hotel Room Damaged Again", "Defendant From Hotel Case Rents at Another Hotel"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a hotel, causing damage of $1,700, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a room at another hotel was damaged after {D} rented it. {DL} says guests did it.",
        state: [E(.document, 3, "Damage Report", "$1,700."), E(.document, 2, "Folio", "Room rented to {D}.")],
        defense: [E(.statement, 1, "Guests", "{DL} says guests did it.")],
        role: "Hotel manager",
        exam: [.direct("What is your position at the hotel?", "\"I am the general manager. I oversee the front desk, housekeeping, and security, and I sign off on every damage report.\""),
               .direct("Who rented the room?", "\"The folio shows the room was rented to {DL} for two nights. {D.He} paid at check-in with a card in {D.his} own name.\""),
               .direct("What did you find in the room?", "\"A torn mattress, broken lamps, holes in the wall, and a shattered bathroom mirror. Housekeeping reported it as soon as the room was checked out.\""),
               .direct("What was the damage total?", "\"$1,700 in repairs and replacement, itemized in our damage report. That does not count the nights the room was out of service.\""),
               .direct("What did the hallway camera show?", "\"People going in and out of the room throughout the night. I counted several different faces, and {DL} was not always among them.\""),
               .direct("What do the keycard logs show?", "\"The room was opened by nine different cards over the two nights. Only two of those belong to {DL}.\""),
               .direct("What did {DL} say?", "\"{D.He} said guests did it after {D.he} rented the room. {D.He} said {D.he} did not know until we called.\""),
               .cross("Were the other guests registered at the hotel?", "\"Not that I can tell. Some of the cards were issued by our desk to {DL}, who could hand them out.\""),
               .cross("Is it possible one guest did most of the damage?", "\"The hallway camera shows one guest carrying a bag in and out several times. I cannot say who that guest was.\""),
               .cross("Did {DL} check out on time?", "\"Yes, {D.he} returned the cards at the desk and left. {D.He} did not look back at the room.\""),
               .cross("Did {DL} pay the extra for the damage?", "\"No, I sent a bill for the full amount, and it was never paid. {DL} did not call me about it either.\""),
               .cross("You cannot say who broke the mirror, can you?", "\"No, I cannot. I know it was broken during {DL}'s stay.\"")],
        theory: ("{D} damaged a hotel room that {D.he} rented.", "{D} rented a room and let guests in who wrecked it without {D.his} knowledge."),
        allocution: "\"Guests wrecked that room after I rented it, and I did not know until the hotel told me. I'm sorry to the hotel. I'll pay for the damage.\"",
        truths: ("The hallway camera showed one guest.", "Keycard logs show nine different cards opened the room."),
        defendant: [.direct("Did you damage that room?", "\"No, I did not. I rented it and stayed there part of the time.\""),
               .direct("Who was in the room?", "\"Friends of mine, and friends of friends. I gave out extra keys and did not keep track of who came and went.\""),
               .direct("Did you know about the damage?", "\"Not until the hotel called me. I was not in the room when it happened.\""),
               .direct("Why did you rent the room?", "\"We were celebrating a birthday. I did not plan for it to get out of hand.\""),
               .direct("Did you see anyone break things?", "\"I never saw it happen with my own eyes. I left for several hours and came back to people I did not know.\""),
               .direct("What will you do now?", "\"I will pay for the damage. I am sorry to the hotel.\""),
               .cross("You rented the room, didn't you?", "\"Yes, I did, and I am responsible for who was in it. I should have been there.\""),
               .cross("You gave out keycards to other people, didn't you?", "\"Yes, I gave out a few. I did not think about what could happen.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes the hotel doubt me. I did not damage anything myself.\""),
               .cross("One guest in the hallway carried a bag in and out, didn't they?", "\"I saw someone like that, and I do not know who it was.\""),
               .cross("You did not pay the bill the hotel sent, did you?", "\"No, I did not, and I should have paid at least part.\"")],
        openings: ("A hotel room rented to {D} was found wrecked, with a torn mattress, broken lamps, and a shattered mirror, $1,700 in damage. The folio is in {D}'s name, and {DL} came before this court in {PRIORDATE} over {PRIOR}, so the hotel knows whom it rented to.", "The defense will present a room that nine different keycards opened over two nights. A name on a folio is not proof of who broke the mirror, and the hotel's own logs show many other guests."),
        closings: ("The folio is in {D}'s name, the damage came during the stay, and the bill was never paid. A renter answers for the room, and {D} handed out the keys that let others in.", "Nine keycards, a hallway full of guests, and a renter who was away for hours. The State has not shown that {D} willfully damaged anything, only that a party got out of hand."),
        timeline: [(0, "{D} checks into a hotel room and receives several keycards."), (0, "The hallway camera records many guests entering and leaving the room overnight."), (1, "Housekeeping finds the room wrecked at checkout."), (2, "The manager sends a $1,700 damage bill that goes unpaid.")],
        identified: "Hotel records.",
        mood: .indifferent)

    static let giftBoxAgain = SmallCases.make(
        key: "story.followup.giftBoxAgain",
        category: .property,
        headlines: ["Another Reception Loses Its Gift Box", "Defendant From Wedding Box Case at New Wedding"],
        law: "misdLarceny",
        spec: "Stole gift cards and cash valued at $700 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a gift box vanished at another reception. A photographer's video showed {D}. {DL} says {D.he} was moving it.",
        state: [E(.video, 3, "Video", "{D} carries the box."), E(.statement, 2, "Guest", "Box missing.")],
        defense: [E(.statement, 1, "Moving It", "{DL} says {D.he} was moving it.")],
        role: "Bride or groom",
        exam: [.direct("Tell the jury what happened at your reception.", "\"We were in the middle of our wedding reception when someone took the gift box from the card table. It held cards and envelopes with about $700 in cash and checks.\""),
               .direct("How did you discover it was missing?", "\"After the toast, my spouse went to put a card in the box and found the table bare. We asked around, and no one had moved it.\""),
               .direct("What does the photographer's video show?", "\"It shows {DL} picking up the box and carrying it out the side door. It is about a minute long, and the box does not come back.\""),
               .direct("Did you know {DL}?", "\"No. We did not recognize {D.him}, and I do not think {D.he} was on our list. We had a seating chart, and {D.his} name was not on it.\""),
               .direct("What was in the box?", "\"About $700 in cards and envelopes from our relatives and friends. Some were checks, which we later canceled, and some were cash.\""),
               .direct("What did you do when you saw the video?", "\"I called the sheriff's office that night, and we gave a deputy the footage the next day. A guest recognized {DL} from another event.\""),
               .direct("How did this affect your day?", "\"It broke my heart. We had planned the reception for a year, and a stranger walking out with the gifts made it feel unsafe.\""),
               .cross("{DL} says {D.he} was moving the box, doesn't {D.he}?", "\"That is what I was told, but nobody asked {D.him} to move it. It was not in anyone's way.\""),
               .cross("Could a relative have asked {DL} to carry the box?", "\"One of my relatives says it is possible. I did not ask anyone to move it.\""),
               .cross("Was {DL} a plus-one of one of your guests?", "\"I have been told that is the claim. I did not see {D.him} come in with anyone.\""),
               .cross("Did {DL} leave with the box through the side door?", "\"Yes, that is on the video. {D.He} did not look around or hide it.\""),
               .cross("You were not in the room when the box was taken, were you?", "\"No, my spouse and I were on the dance floor. I know only what the video and the guests tell me.\"")],
        theory: ("{D} carried a wedding reception's gift box out the side door.", "{D} was a plus-one who moved a box at a relative's request."),
        allocution: "\"I was only moving that gift box, and I was there as a plus-one. I didn't take it. I'm sorry to the couple whose gifts went missing, and I'll help any way I can.\"",
        truths: ("{DL} was not on the guest list.", "The hosts' relative said {DL} was asked to carry the box."),
        defendant: [.direct("Did you take the box?", "\"No, I moved it, and I did not take it. I carried it out the side door at someone else's request, and I never kept it.\""),
               .direct("Why did you move it?", "\"A relative of the couple asked me to carry it to the car. I did not know it was the gift box.\""),
               .direct("Were you a guest?", "\"I came as a plus-one with a friend. My name was not on the list, but my friend was.\""),
               .direct("Where did you take the box?", "\"Out the side door, toward the parking lot. I meant to put it where the relative told me.\""),
               .direct("What happened to the box after that?", "\"I set it down by a car and went back inside. I did not see anyone pick it up.\""),
               .direct("What do you want the couple to know?", "\"I am sorry. I should have asked more before carrying anything out.\""),
               .cross("You carried a gift box out of a reception, didn't you?", "\"Yes, I did, and I know how that looks on the video.\""),
               .cross("Your name was not on the guest list, was it?", "\"No, I was a plus-one. I did not think my name needed to be there.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and that makes me careful now. I did not take that box.\""),
               .cross("The box has not been found, has it?", "\"I do not know where it is. I set it down by a car in the lot and never saw it again after that.\""),
               .cross("You did not tell anyone you were moving it, did you?", "\"No. The relative did not seem to need a name.\"")],
        openings: ("In the middle of a wedding reception, a gift box holding about $700 in cards and envelopes vanished from the card table. The photographer's video shows {D} carrying it out the side door, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a plus-one who was asked by a relative of the couple to carry the box. A person who walks past a photographer with the box in hand is not hiding anything."),
        closings: ("A card table left bare, a photographer's video of {D} walking out the side door with the box, and $700 never seen again. {D} was not on the guest list and carried it away.", "A relative's request, a plus-one, and a box carried in front of a camera and a room full of people. The State has not shown that {D} meant to keep it, and a person who works in the open is not hiding a theft."),
        timeline: [(0, "The toast: the couple's gift box sits on the card table at the reception."), (0, "The photographer's video records {D} carrying the box out the side door."), (0, "The couple discovers the table bare and calls the sheriff's office."), (1, "The couple gives the video to a deputy.")],
        identified: "A video.",
        mood: .indifferent)

    static let busAgain = SmallCases.make(
        key: "story.followup.busAgain",
        category: .traffic,
        headlines: ["Driver Passes Stopped Bus Again", "Defendant From Stop-Arm Case Passes Another Bus"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, passing a stopped school bus, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a car passed a stopped bus with its arm out. The plate belonged to {D}. {DL} says the arm was not extended.",
        state: [E(.video, 3, "Bus Camera", "A car passes the stop arm."), E(.document, 2, "Registration", "{D}'s plate.")],
        defense: [E(.statement, 1, "Arm Not Out", "{DL} says the arm was not extended.")],
        role: "School bus driver",
        exam: [.direct("What is your job with the school district?", "\"I am a school bus driver for the county. I have driven the same morning route for nine years, and I know every stop on it.\""),
               .direct("What happened at the stop that morning?", "\"I stopped on a two-lane road, put on my flashers, and extended the stop arm. Four children were crossing in front of the bus when the car came up behind us.\""),
               .direct("What did the bus camera show?", "\"It shows a car coming up behind the bus, moving to the left, and driving past the stop arm while the children were still in the road.\""),
               .direct("How many children were crossing at that moment?", "\"Four, all between six and ten years old. One of them had to step back to let the car go by.\""),
               .direct("How did you identify the car?", "\"The camera caught the plate, which is registered to {DL}. I reported the plate and the time to the transportation office as soon as I got to the school.\""),
               .direct("Was the stop arm extended?", "\"Yes, I put it out as I always do, and the camera shows it extended with the lights flashing on the side of the bus.\""),
               .direct("How did you feel afterward?", "\"I was shaking. In nine years, I have never seen a car pass that close to children getting on a bus.\""),
               .cross("{DL} says the arm was not extended, doesn't {D.he}?", "\"That is what {D.he} says. The camera shows the arm out, and I put it out myself, so I know that it was extended.\""),
               .cross("Was the stop-arm light working properly that week?", "\"One of the lights on the arm was dim that week. I had reported it to the shop, and it had not been fixed by that morning.\""),
               .cross("Could {DL} have missed the arm if the light was dim?", "\"It is possible, if the sun was in {D.his} eyes and the light was weak. I cannot say what {D.he} saw.\""),
               .cross("Did {DL} brake before passing the bus?", "\"I did not see brake lights on the car. It kept going at about the same speed all the way past.\""),
               .cross("You cannot say who was driving that car, can you?", "\"No, I cannot. I can tell you the plate from the camera, but I did not see the driver's face.\"")],
        theory: ("{D} drove past a stopped school bus with its stop arm out while children crossed.", "{D} did not see the stop arm and did not know children were crossing."),
        allocution: "\"I didn't know the bus arm was out, and I may have passed it without seeing. I'm sorry for the children at that stop. I'll slow way down around buses from now on.\"",
        truths: ("The camera shows the arm extended.", "The bus's stop-arm light had burned out."),
        defendant: [.direct("Did you see the bus that morning?", "\"I saw a bus ahead of me, but I did not see the stop arm. I did not realize it was out until much later.\""),
               .direct("Why did you go around it?", "\"I did not know the arm was out. I thought the bus was pulling over to the side, and I went around it without thinking.\""),
               .direct("Did you see the children?", "\"Not until I was almost past. I was looking at the road ahead, and the sun was in my eyes.\""),
               .direct("Were you in a hurry that day?", "\"I was late for work, and I should have paid closer attention to what I was doing. I let the hurry decide for me.\""),
               .direct("What have you thought about since?", "\"Every day I think about those children and what could have happened. I am sorry for what I did.\""),
               .direct("What will you do now?", "\"I will slow down around every bus I see, and I will stop whenever there is any doubt. I will never pass a stopped bus again.\""),
               .cross("The camera shows the arm out, doesn't it?", "\"I understand that now, after seeing the video. I did not see it that morning, and I will not argue with the picture.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and I know that makes it harder to believe I missed a stop arm. I did miss it, and I am sorry.\""),
               .cross("The plate on the video is yours, isn't it?", "\"Yes, it is my plate and my car. I did not try to deny that to anyone.\""),
               .cross("A light on the arm was dim that week, wasn't it?", "\"I have heard that, and I think it may have been part of why I did not notice it.\""),
               .cross("Children were in the road when you passed, weren't they?", "\"I understand they were, and that is what troubles me most. I did not see them until later.\"")],
        openings: ("A school bus stopped on a two-lane road with its flashers on and its stop arm out while four children crossed, and a car passed on the left. The bus camera caught the plate, which belongs to {D}, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a driver who did not see the stop arm, which had a dim light that week. A missed arm is a mistake that frightened everyone, but it is not a willful disregard of children."),
        closings: ("Flashers, a stop arm, four children in the road, and a car that did not slow down. The plate belongs to {D}, and the driver had every chance to see a school bus stopped on a quiet road.", "A dim light on the arm, a driver with the sun in {D.his} eyes, and a mistake that no child paid for. The State has not shown willful disregard, only that {D} did not see what was there."),
        timeline: [(0, "The bus stops on a two-lane road and extends its stop arm with the flashers on."), (0, "A car passes on the left while four children are crossing, and the bus camera records the plate."), (0, "The bus driver reports the plate to the transportation office.")],
        identified: "A bus camera.",
        mood: .wantsConviction)

    static let lockerAgain = SmallCases.make(
        key: "story.followup.lockerAgain",
        category: .property,
        headlines: ["Locker Cut at Second Gym", "Defendant From Gym Wallet Case Signs In as Guest Again"],
        law: "misdLarceny",
        spec: "Stole a wallet and $150 in cash belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a locker at another gym was cut and a wallet taken. {D} had signed in as a guest. {DL} says {D.he} found it. The loss was put at $150.",
        state: [E(.document, 3, "Guest Log", "{D} signed in."), E(.digital, 3, "Card Charge", "The wallet's card was used.")],
        defense: [E(.statement, 1, "Found", "{DL} says {D.he} found the wallet.")],
        role: "Gym member",
        exam: [.direct("Tell the jury what happened at your gym.", "\"I belong to a gym on the north side of town. I finished a workout, went to my locker, and found the lock cut and my wallet gone.\""),
               .direct("What did you have in the locker?", "\"My wallet with about $150 in cash and two cards, along with my keys and a change of clothes. The keys and clothes were left behind.\""),
               .direct("How was the lock damaged?", "\"The shackle was cut clean through, the way a bolt cutter would do it. My own combination lock was lying on the floor beside the bench.\""),
               .direct("What does the guest log show?", "\"A guest named {DL} signed in about forty minutes before I found the locker open. That is the only guest who signed in during my workout.\""),
               .direct("What happened to your cards?", "\"One of them was used at a store a few miles away that afternoon. I canceled both as soon as I saw the charge.\""),
               .direct("How has this affected you?", "\"I do not leave anything in a locker now. I feel uneasy at a place where I used to feel safe, and I carry my wallet in my gym bag.\""),
               .cross("{DL} says {D.he} found the wallet, doesn't {D.he}?", "\"The desk staff told me so afterward. But my wallet was inside a locked locker, so I do not know where {D.he} could have found it.\""),
               .cross("Isn't it possible someone else cut the lock before {DL} came in?", "\"It is possible, but I do not know of anyone else. The cut lock was on the floor by the bench where {DL} had been.\""),
               .cross("Did you see {DL} near your locker?", "\"No, I did not. I was on the other side of the building at the time.\""),
               .cross("Did the store camera show who used your card?", "\"A deputy told me the store camera showed a different person than {DL}. I have not seen the footage myself.\""),
               .cross("Was a bolt cutter found with {DL}?", "\"I was told one was in {D.his} bag. I never saw that bag opened, so I cannot say.\"")],
        theory: ("{D} cut a gym locker and took a member's wallet.", "{D} found a wallet on the gym floor and meant to turn it in."),
        allocution: "\"I found that wallet and meant to turn it in, and I had signed in as a guest. I never cut any locker. I'm sorry to the gym and to the member who lost it.\"",
        truths: ("A bolt cutter was in the bag.", "A different person used the card at a store."),
        defendant: [.direct("Did you cut that locker's lock?", "\"No, I did not. I never cut anything at that gym.\""),
               .direct("How did you come across the wallet?", "\"I found it on the floor near the lockers when I walked in. It was lying by a bench, and I picked it up.\""),
               .direct("What did you plan to do with it?", "\"I meant to turn it in at the front desk. I put it in my bag and got distracted by a call before I reached the desk.\""),
               .direct("Why did you sign in as a guest?", "\"A friend who is a member invited me to work out with {D.him}. I signed in at the desk like every other guest.\""),
               .direct("Why was a bolt cutter in your bag?", "\"It is from my job. I use it at work, and I carry it in my gym bag because I go straight from work.\""),
               .direct("What do you want the member to know?", "\"I am sorry that you lost your wallet and your sense of safety. I never meant to keep it.\""),
               .cross("You were a guest who signed in forty minutes before the lock was found cut, weren't you?", "\"Yes, I signed in, and I know the timing looks bad. I was working out with a friend the whole time.\""),
               .cross("The wallet was in your gym bag, wasn't it?", "\"Yes, because I picked it up off the floor and put it there. I should have handed it to the desk right away.\""),
               .cross("You were before this court in {PRIORDATE} over {PRIOR}, weren't you?", "\"Yes, and I know why that history makes you doubt me. I would not take a wallet from a locker.\""),
               .cross("Your bag held a bolt cutter, didn't it?", "\"Yes, for my job. I have never used it at the gym.\""),
               .cross("You did not give the wallet to the desk, did you?", "\"No, I did not, and I regret that. I meant to and then I forgot until a deputy called.\"")],
        openings: ("A gym member's locker was cut open and a wallet with $150 and two cards was taken. {D} had signed in as a guest forty minutes earlier, a bolt cutter was in {D.his} bag, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will present a guest who found a wallet on the floor and meant to turn it in. A different person used the card at a store, and a bolt cutter that comes from a job is not a burglary."),
        closings: ("A locker cut clean, a guest who signed in forty minutes earlier, and a bolt cutter in the bag. The wallet's card was used within hours, and {D} was the only guest in the building.", "A wallet found on a gym floor, a card used by someone else, and a bolt cutter that belongs to a job. The State has not shown that {D} cut that lock, and a guest who signs in by name is not hiding anything."),
        timeline: [(0, "{D} signs in at a gym as a guest of a member."), (0, "About forty minutes later, a member finds a locker lock cut and a wallet gone."), (0, "That afternoon, one of the wallet's cards is used at a store."), (1, "A deputy reviews the guest log and the gym's video.")],
        identified: "A guest log.",
        mood: .indifferent)

    static let ediblesAgain = SmallCases.make(
        key: "story.followup.ediblesAgain",
        category: .drugs,
        headlines: ["Gummies Found Again at Gate", "Defendant From Festival Case Searched Again"],
        law: "possMarijuana",
        spec: "Possessed marijuana, in the form of edible gummies, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, security found gummies in {D}'s bag at another event. {DL} says they were hemp.",
        state: [E(.physical, 3, "Gummies", "30 gummies.", .search), E(.forensic, 3, "Lab", "THC.")],
        defense: [E(.statement, 1, "Hemp", "{DL} says they were hemp.")],
        role: "Security supervisor",
        exam: [.direct("What is your position at the event?", "\"I am the security supervisor. I run the gate team, and my officers check bags and bring anything prohibited to me.\""),
               .direct("What did the search turn up?", "\"In {DL}'s bag, a plastic container holding thirty gummies in several colors. One of my officers flagged them at the gate.\""),
               .direct("Why were they flagged?", "\"They were not in a sealed package, and one of my officers noticed the smell. We do not allow anything that could be a drug in the event.\""),
               .direct("What did the lab report say?", "\"The lab found THC in the gummies. The report lists the amount, and it is well above what hemp products carry.\""),
               .direct("What did the container look like?", "\"A clear plastic tub with no label on it. There was a faded sticker in the bag that might have come from a package.\""),
               .direct("What did you do?", "\"I held the bag, called the sheriff's office, and let a deputy take over. The deputy collected the gummies as evidence.\""),
               .cross("Did the package say hemp?", "\"A faded sticker in the bag said something about hemp. I could not read all of it.\""),
               .cross("Was the sticker legible when you saw it?", "\"Partly. I could read some words, and the rest was washed out.\""),
               .cross("Did the label say federally legal?", "\"I am told the full label said hemp-derived and federally legal. I could not read that part myself.\""),
               .cross("Did {DL} try to hide the gummies?", "\"No, {D.he} handed the bag over without any fuss and opened it for the officer. {D.He} answered every question we asked at the gate.\""),
               .cross("You are not a chemist, are you?", "\"No, I am not. I rely on the lab for what is in them.\"")],
        theory: ("{D} carried thirty gummies containing THC into an event.", "{D} believed the gummies were legal hemp and carried them in good faith."),
        allocution: "\"I thought those gummies were hemp, and the label was faded. I know I was in this court before, and I should have read it. I'm sorry to the event security and to the other guests.\"",
        truths: ("The label listed THC.", "The package said 'hemp-derived, federally legal' with no THC warning."),
        defendant: [.direct("Were those gummies yours?", "\"Yes, they were mine. I bought them from a shop and brought them in my bag.\""),
               .direct("What did you think they were?", "\"Hemp gummies. The package said hemp-derived and federally legal, and there was no warning about THC.\""),
               .direct("Why was the label faded?", "\"The package had been in my bag for weeks, and the sticker rubbed off against my keys. I did not look at it again.\""),
               .direct("Did you know they could contain THC?", "\"No, I did not. I thought they were legal and safe to carry.\""),
               .direct("How did you act at the gate?", "\"I handed over the bag and answered every question the officer asked. Nothing was hidden or zipped away.\""),
               .direct("What do you want the event security to know?", "\"I am sorry for the disruption at your gate. I should have read the label again before I brought it.\""),
               .cross("The lab found THC in the gummies, didn't it?", "\"So the report says. I did not know, and I never had them tested myself.\""),
               .cross("You were here before, in {PRIORDATE}, over {PRIOR}, weren't you?", "\"Yes, and that is why I tried to buy something legal. I thought I was following the rules.\""),
               .cross("The container had no label on it, did it?", "\"No, I had moved them to a tub. The original package was in my bag, and the sticker was on it.\""),
               .cross("You bought them from a shop, didn't you?", "\"Yes, from a shop that sells hemp products. I did not ask about THC.\""),
               .cross("You did not read the label again before bringing them, did you?", "\"No, I did not, and I should have. I trusted what the shop told me, and I never looked at it again once I got home.\"")],
        openings: ("Event security found a tub of thirty gummies in {D}'s bag at the gate, and the lab found THC in them. {DL} says the package said hemp, and {DL} came before this court in {PRIORDATE} over {PRIOR}, so the court has seen a similar charge from {D.him}.", "The defense will present a package labeled hemp-derived and federally legal, and a person who handed over the bag without a fuss. A good-faith belief that a product is legal matters, and the State must prove otherwise."),
        closings: ("A tub of gummies, thirty in all, a lab report that finds THC, and a defendant who had been before this court on a similar matter. The lab says what they were.", "A hemp label, a legal shop, and an honest answer at the gate. The State has not shown that {D} knew the gummies held THC, and a person who hands over the bag is not hiding anything."),
        timeline: [(0, "{D} arrives at the event gate and an officer searches {D.his} bag."), (0, "Security finds a tub of thirty gummies and calls the sheriff's office."), (5, "The lab finds THC in the gummies.")],
        identified: "A lab report.",
        mood: .indifferent,
        doctrines: ["searchSeizure"])

    static let landlordAgain = SmallCases.make(
        key: "story.followup.landlordAgain",
        category: .whiteCollar,
        headlines: ["Second Renter Pays Deposit on Unavailable Apartment", "Defendant From Fake Landlord Case Lists Again"],
        law: "falsePretenses",
        spec: "Obtained $1,200 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} paid {D} a deposit for an apartment {D.he} did not control. {DL} says the owner agreed.",
        state: [E(.digital, 3, "Listing", "A listing in {D}'s name."), E(.document, 3, "Payment", "$1,200 to {D}.")],
        defense: [E(.statement, 1, "Owner", "{DL} says the owner agreed.")],
        role: "Renter",
        exam: [.direct("What were you looking for when you found this listing?", "\"I needed a place to live after my lease ended. I answered an online listing for a two-bedroom apartment, and the listing was posted under {DL}'s name.\""),
               .direct("What did {DL} ask of you?", "\"A $1,200 deposit to hold the apartment. {D.He} told me the money would go to the owner and that I could move in at the start of the next month.\""),
               .direct("Did you pay the deposit?", "\"Yes, I did. I sent $1,200 to {D.him} that same week, and I have the payment record on my phone and a copy of our text messages.\""),
               .direct("What happened when you went to the apartment?", "\"I found the actual owner there, doing repairs. The owner told me {DL} did not control the apartment and had never been given permission to rent it.\""),
               .direct("Did the owner know {DL}?", "\"The owner said they had never heard of {D.him}. The owner had not listed the apartment for rent at all, and no one had paid anything.\""),
               .direct("How has this affected you?", "\"I lost money I could not afford to lose. I stayed with my brother for six weeks while I looked for another place, and I had to put off buying winter clothes for my kids.\""),
               .direct("What did you do after that?", "\"I reported it to the sheriff's office. I gave them the listing, the payment record, and the owner's statement.\""),
               .cross("{DL} says the owner agreed to the rental, doesn't {D.he}?", "\"That is what {D.he} says. The owner told me otherwise, and the owner was standing in the apartment when I asked.\""),
               .cross("Did you ever speak with {DL} on the phone?", "\"A few times, and {D.he} sounded friendly and sure of what {D.he} was doing. That is part of why I trusted {D.him} with the deposit.\""),
               .cross("Did the listing include photos of the apartment?", "\"Yes, photos taken from inside, and they matched the place I saw later. I assumed they were real, and they were of that apartment.\""),
               .cross("Did {DL} give you a written agreement?", "\"Only a text message with the deposit terms. There was no lease and no receipt on any letterhead.\""),
               .cross("You cannot say what {DL} and the owner discussed, can you?", "\"No, I cannot. I can tell you only what the owner said to me when I arrived at the door.\"")],
        theory: ("{D} took a deposit for an apartment {D.he} did not control.", "{D} believed {D.he} was acting as the owner's agent under written authority."),
